insert into public.content_items (kind, slug, locale, title, body, tags, position, plus_only, sensitive, level) values
  ('daily_idea', 'di-voice-note', 'pt-BR', 'Mande um áudio curto', 'Dez segundos dizendo algo de que você gosta. Sem cobrar resposta.', '{free,keep_romance}', 100, false, false, null),
  ('daily_idea', 'di-voice-note', 'en', 'Send a short voice note', 'Ten seconds saying something you like. No reply expected.', '{free,keep_romance}', 100, false, false, null),
  ('daily_idea', 'di-tea', 'pt-BR', 'Prepare uma bebida quente', 'Sem perguntar. Só deixe pronta quando a pessoa chegar.', '{free,cheap,living_together}', 101, false, false, null),
  ('daily_idea', 'di-tea', 'en', 'Make a warm drink', 'No asking. Just have it ready when they arrive.', '{free,cheap,living_together}', 101, false, false, null),
  ('daily_idea', 'di-song', 'pt-BR', 'Toquem uma música de vocês', 'Uma só, no fim do dia, sem pressa.', '{free,reconnect}', 102, false, false, null),
  ('daily_idea', 'di-song', 'en', 'Play a song of yours', 'Just one, at the end of the day, no rush.', '{free,reconnect}', 102, false, false, null),
  ('daily_idea', 'di-compliment', 'pt-BR', 'Faça um elogio específico', 'Não "você é lindo", e sim "gostei de como você resolveu aquilo".', '{free,keep_romance}', 103, false, false, null),
  ('daily_idea', 'di-compliment', 'en', 'Give a specific compliment', 'Not "you are great", but "I liked how you handled that".', '{free,keep_romance}', 103, false, false, null),
  ('daily_idea', 'di-walk-ten', 'pt-BR', 'Caminhem dez minutos', 'Em volta do quarteirão, sem celular.', '{free,reconnect}', 104, false, false, null),
