  ('daily_idea', 'di-note-pocket', 'en', 'Hide a note', 'In a coat, a bag or on the bathroom mirror.', '{free,keep_romance}', 108, false, false, null),
  ('daily_idea', 'di-breakfast', 'pt-BR', 'Café da manhã na cama', 'Pode ser simples: pão, fruta e um bilhete.', '{cheap,keep_romance}', 109, false, false, null),
  ('daily_idea', 'di-breakfast', 'en', 'Breakfast in bed', 'It can be simple: bread, fruit and a note.', '{cheap,keep_romance}', 109, false, false, null),
