insert into public.content_items (kind, slug, locale, title, body, parent_slug, position, plus_only) values
  ('lesson', 'gratitude-7-d4', 'pt-BR', 'Agradeça o invisível', 'Hoje, agradeça algo que a pessoa faz sem ninguém pedir.', 'gratitude-7', 4, true),
  ('lesson', 'gratitude-7-d4', 'en', 'Thank the invisible', 'Today, thank something they do without being asked.', 'gratitude-7', 4, true),
  ('lesson', 'gratitude-7-d5', 'pt-BR', 'Escreva um bilhete', 'Três linhas: o que você viu, o que sentiu, o que agradece.', 'gratitude-7', 5, true),
  ('lesson', 'gratitude-7-d5', 'en', 'Write a note', 'Three lines: what you saw, how it felt, what you are thankful for.', 'gratitude-7', 5, true),
  ('lesson', 'gratitude-7-d6', 'pt-BR', 'Agradeça um esforço', 'Pense em algo difícil que a pessoa enfrentou e reconheça.', 'gratitude-7', 6, true),
  ('lesson', 'gratitude-7-d6', 'en', 'Thank an effort', 'Think of something hard they faced and acknowledge it.', 'gratitude-7', 6, true),
  ('lesson', 'gratitude-7-d7', 'pt-BR', 'Releia a semana', 'Releiam o que agradeceram e escolham um gesto para continuar.', 'gratitude-7', 7, true),
  ('lesson', 'gratitude-7-d7', 'en', 'Reread the week', 'Reread what you thanked each other for and pick one gesture to keep.', 'gratitude-7', 7, true),
  ('lesson', 'fight-less-d3', 'pt-BR', 'Nomeie o que sente', 'Antes de reagir, diga em uma palavra o que está sentindo.', 'fight-less', 3, true),
  ('lesson', 'fight-less-d3', 'en', 'Name what you feel', 'Before reacting, say in one word what you are feeling.', 'fight-less', 3, true),
  ('lesson', 'fight-less-d4', 'pt-BR', 'Pergunte antes de supor', 'Troque a suposição por uma pergunta curta e curiosa.', 'fight-less', 4, true),
  ('lesson', 'fight-less-d4', 'en', 'Ask before assuming', 'Swap the assumption for a short, curious question.', 'fight-less', 4, true),
  ('lesson', 'fight-less-d5', 'pt-BR', 'Um pedido claro', 'Peça uma coisa específica, no presente, em vez de reclamar do passado.', 'fight-less', 5, true),
  ('lesson', 'fight-less-d5', 'en', 'One clear request', 'Ask for one specific thing, in the present, instead of complaining about the past.', 'fight-less', 5, true),
  ('lesson', 'fight-less-d6', 'pt-BR', 'Reparo rápido', 'Escolha uma frase de reparo e combine quando usá-la.', 'fight-less', 6, true),
  ('lesson', 'fight-less-d6', 'en', 'Quick repair', 'Pick a repair sentence and agree on when to use it.', 'fight-less', 6, true),
  ('lesson', 'fight-less-d7', 'pt-BR', 'O que funcionou', 'Conte o que ajudou esta semana e o que vocês querem manter.', 'fight-less', 7, true),
  ('lesson', 'fight-less-d7', 'en', 'What worked', 'Share what helped this week and what you want to keep.', 'fight-less', 7, true)
